package prototype;
import android.graphics.*;import java.io.*;import java.nio.*;import java.util.*;import com.google.gson.*;
/** Independent pixel fixtures and API invariants, separate from the plugin entry point. */
public final class GraphicsProbe {
 private static final String PNG="iVBORw0KGgoAAAANSUhEUgAAAAgAAAAGCAYAAAD+Bd/7AAAAi0lEQVR4nA3KMQEEIQxFwThYB9Q06yAOaKjjAAffwTpITXMOEEGNoXdMPWZmFHtwK4S9yJy0xrLg2MCsPpRa8PoS1VFtZA1WHZyqG3qh9BfvTvSGepB9sLo4/btBL0WOqxEKpEFKLH0c5Q3TKbPhM4g50BQ5P9ZMzvzdsBtlB74HsYX2R+5k7R9nL/4pL2chSpNnCwAAAABJRU5ErkJggg==";
 private static final String GIF="R0lGODlhAQABAIAAAP8AAAD/ACH5BAQBAAAALAAAAAABAAEAAAICRAEAIfkEBAEAAAAsAAAAAAEAAQAAAgJMAQA7";
 private static JsonArray checks;private static void expect(boolean ok,String label){if(!ok)throw new AssertionError(label);checks.add(label);}
 private static int[] pixels(Bitmap b){int[] p=new int[b.getWidth()*b.getHeight()];b.getPixels(p,0,b.getWidth(),0,0,b.getWidth(),b.getHeight());return p;}
 private static int color(int x,int y){return Color.argb(255,x*30,y*40,(x+y)*15);}
 private static byte[] encode(Bitmap b,Bitmap.CompressFormat f){ByteArrayOutputStream out=new ByteArrayOutputStream();expect(b.compress(f,100,out),"encode "+f);return out.toByteArray();}
 public static String run()throws Exception {
  checks=new JsonArray();List<Bitmap> owned=new ArrayList<>();
  try{
   Bitmap tile=Bitmap.createBitmap(2,2,Bitmap.Config.ARGB_8888);owned.add(tile);int[] colors={Color.RED,Color.GREEN,Color.BLUE,Color.WHITE};tile.setPixels(colors,0,2,0,0,2,2);expect(Arrays.equals(pixels(tile),colors),"ARGB pixels");
   int[] reversed=new int[4];tile.getPixels(reversed,2,-2,0,0,2,2);expect(Arrays.equals(reversed,new int[]{Color.BLUE,Color.WHITE,Color.RED,Color.GREEN}),"negative read stride");
   tile.setPixels(reversed,2,-2,0,0,2,2);expect(Arrays.equals(pixels(tile),colors),"negative write stride");tile.getPixels(new int[0],-100,0,0,0,0,0);tile.setPixels(new int[0],-100,0,0,0,0,0);expect(true,"zero-sized pixel operations");
   Bitmap reordered=Bitmap.createBitmap(2,2,Bitmap.Config.ARGB_8888);owned.add(reordered);Canvas c=new Canvas(reordered);c.drawBitmap(tile,new Rect(0,0,1,2),new Rect(1,0,2,2),null);c.drawBitmap(tile,new Rect(1,0,2,2),new Rect(0,0,1,2),null);expect(Arrays.equals(pixels(reordered),new int[]{Color.GREEN,Color.RED,Color.WHITE,Color.BLUE}),"exact tile reorder");
   Bitmap transformed=Bitmap.createBitmap(8,6,Bitmap.Config.ARGB_8888);owned.add(transformed);Canvas tr=new Canvas(transformed);Paint paint=new Paint();paint.setColor(Color.RED);int save=tr.save();tr.translate(2,1);tr.scale(2,2);tr.drawRect(0,0,1,1,paint);tr.restoreToCount(save);paint.setColor(Color.BLUE);tr.drawRect(0,0,1,1,paint);expect(transformed.getPixel(2,1)==Color.RED&&transformed.getPixel(3,2)==Color.RED&&transformed.getPixel(0,0)==Color.BLUE&&transformed.getPixel(1,1)==Color.TRANSPARENT,"matrix and save restore");
   tr.translate(100,100);tr.drawColor(Color.GREEN);expect(Arrays.stream(pixels(transformed)).allMatch(x->x==Color.GREEN),"drawColor ignores matrix");
   Bitmap alpha=Bitmap.createBitmap(1,1,Bitmap.Config.ARGB_8888);owned.add(alpha);alpha.setPixel(0,0,0x80ff0000);ByteBuffer raw=ByteBuffer.allocate(8);raw.position(2);alpha.copyPixelsToBuffer(raw);expect(raw.position()==6&&(raw.get(2)&255)==128&&raw.get(3)==0&&raw.get(4)==0&&(raw.get(5)&255)==128,"premultiplied RGBA buffer and position");
   raw.position(2);Bitmap alphaCopy=Bitmap.createBitmap(1,1,Bitmap.Config.ARGB_8888);owned.add(alphaCopy);alphaCopy.copyPixelsFromBuffer(raw);expect(raw.position()==6&&alphaCopy.getPixel(0,0)==0x80ff0000,"premultiplied buffer import");
   Bitmap under=Bitmap.createBitmap(1,1,Bitmap.Config.ARGB_8888);owned.add(under);under.eraseColor(Color.BLUE);new Canvas(under).drawBitmap(alpha,0,0,null);int blended=under.getPixel(0,0);expect(Color.alpha(blended)==255&&Math.abs(Color.red(blended)-128)<=1&&Math.abs(Color.blue(blended)-127)<=1,"source-over alpha compositing");
   Bitmap immutable=tile.copy(Bitmap.Config.ARGB_8888,false);owned.add(immutable);boolean failed=false;try{immutable.setPixel(0,0,0);}catch(IllegalStateException e){failed=true;}expect(failed&&Arrays.equals(pixels(immutable),colors),"immutable copy");
   tile.setDensity(240);Bitmap crop=Bitmap.createBitmap(tile,1,0,1,2);owned.add(crop);expect(crop.getWidth()==1&&crop.getHeight()==2&&crop.getDensity()==240&&Arrays.equals(pixels(crop),new int[]{Color.GREEN,Color.WHITE}),"crop pixels and density");
   Bitmap scaled=Bitmap.createScaledBitmap(tile,4,4,false);owned.add(scaled);expect(scaled.getDensity()==240&&scaled.getPixel(0,0)==Color.RED&&scaled.getPixel(3,0)==Color.GREEN&&scaled.getPixel(0,3)==Color.BLUE,"nearest scale and density");expect(Bitmap.createScaledBitmap(tile,2,2,false)==tile,"identity scale");
   byte[] fixture=Base64.getDecoder().decode(PNG);Bitmap pattern=BitmapFactory.decodeByteArray(fixture,0,fixture.length);owned.add(pattern);int[] expected=new int[48];for(int y=0;y<6;y++)for(int x=0;x<8;x++)expected[y*8+x]=color(x,y);expect(pattern.getWidth()==8&&pattern.getHeight()==6&&!pattern.isMutable()&&Arrays.equals(pixels(pattern),expected),"independent PNG fixture");
   BitmapFactory.Options options=new BitmapFactory.Options();options.inJustDecodeBounds=true;options.inSampleSize=2;options.inDensity=160;options.inTargetDensity=320;expect(BitmapFactory.decodeByteArray(fixture,0,fixture.length,options)==null&&options.outWidth==8&&options.outHeight==6&&options.outMimeType.equals("image/png"),"bounds ignore scaling");
   options.inJustDecodeBounds=false;options.inMutable=true;Bitmap density=BitmapFactory.decodeByteArray(fixture,0,fixture.length,options);owned.add(density);expect(density.getWidth()==8&&density.getHeight()==6&&options.outWidth==8&&options.outHeight==6&&density.getDensity()==320&&density.isMutable(),"sample then density scaling");
   options.inScaled=false;Bitmap sampled=BitmapFactory.decodeByteArray(fixture,0,fixture.length,options);owned.add(sampled);expect(sampled.getWidth()==4&&sampled.getHeight()==3&&options.outWidth==4&&options.outHeight==3&&sampled.getDensity()==160,"sample without density scaling");
   options.inScaled=true;options.inScreenDensity=160;Bitmap screen=BitmapFactory.decodeByteArray(fixture,0,fixture.length,options);owned.add(screen);expect(screen.getWidth()==4&&screen.getDensity()==160,"screen density exemption");
   options.inJustDecodeBounds=true;expect(BitmapFactory.decodeByteArray(new byte[]{1,2,3},0,3,options)==null&&options.outWidth==-1&&options.outHeight==-1,"invalid decode metadata");
   byte[] png=encode(pattern,Bitmap.CompressFormat.PNG);expect(png.length>8&&(png[0]&255)==137&&png[1]==80,"PNG signature");Bitmap pngRound=BitmapFactory.decodeStream(new ByteArrayInputStream(png));owned.add(pngRound);expect(Arrays.equals(pixels(pngRound),expected),"PNG pixel roundtrip");
   byte[] jpeg=encode(pattern,Bitmap.CompressFormat.JPEG);expect((jpeg[0]&255)==255&&(jpeg[1]&255)==216,"JPEG signature");Bitmap jpegRound=BitmapFactory.decodeByteArray(jpeg,0,jpeg.length);owned.add(jpegRound);expect(jpegRound.getWidth()==8&&jpegRound.getHeight()==6,"JPEG dimensions");
   byte[] webp=encode(pattern,Bitmap.CompressFormat.WEBP);expect(webp[0]=='R'&&webp[1]=='I'&&webp[8]=='W'&&webp[9]=='E',"WebP signature");Bitmap webpRound=BitmapFactory.decodeByteArray(webp,0,webp.length);owned.add(webpRound);expect(webpRound.getWidth()==8&&webpRound.getHeight()==6,"WebP dimensions");
   ByteArrayOutputStream lossless=new ByteArrayOutputStream();expect(!pattern.compress(Bitmap.CompressFormat.WEBP_LOSSLESS,100,lossless)&&lossless.size()==0,"unsupported lossless mode is explicit");
   Paint text=new Paint();expect(text.getTypeface()==null&&text.isAntiAlias(),"modern default paint");expect(text.setTypeface(Typeface.MONOSPACE)==Typeface.MONOSPACE,"setTypeface result");text.setTextSize(20);float measure=text.measureText("ABCD");expect(measure>0,"browser text metrics");Paint textCopy=new Paint(text);textCopy.setTextScaleX(2);expect(Math.abs(textCopy.measureText("ABCD")-2*measure)<0.02&&text.getTextScaleX()==1,"paint copy and text scale");textCopy.setTextSize(0);expect(textCopy.measureText("ABCD")==0,"zero-size text metrics");
   Bitmap decorated=Bitmap.createBitmap(160,60,Bitmap.Config.ARGB_8888);owned.add(decorated);Canvas dc=new Canvas(decorated);Paint red=new Paint();red.setColor(Color.RED);dc.drawRoundRect(new RectF(0,0,20,20),8,8,red);expect(decorated.getPixel(10,10)==Color.RED&&Color.alpha(decorated.getPixel(0,0))<64,"rounded shape");text.setColor(Color.GREEN);dc.drawText("ABCD",30,35,text);int ink=0;int[] drawn=pixels(decorated);for(int y=0;y<60;y++)for(int x=30;x<160;x++)if(Color.alpha(drawn[y*160+x])>0)ink++;expect(ink>10,"text draws pixels");
   var legacy=tachiyomi.decoder.ImageDecoder.Companion.newInstance(new ByteArrayInputStream(fixture),false,null);expect(legacy.getWidth()==8&&legacy.getHeight()==6,"legacy decoder dimensions");Bitmap region=legacy.decode(new Rect(2,1,5,4),1);owned.add(region);expect(region.getWidth()==3&&region.getPixel(0,0)==color(2,1)&&region.getPixel(2,2)==color(4,3),"legacy region pixels");legacy.recycle();failed=false;try{legacy.getWidth();}catch(IllegalStateException e){failed=true;}expect(failed,"legacy decoder recycle");
   try(var decoder=ca.mpreg.imagedecoder.ImageDecoder.Companion.open(new ByteArrayInputStream(fixture),false)){expect(!decoder.isHdr(),"PNG is SDR");try(var frame=decoder.decodeNext()){ByteBuffer data=frame.getImage();expect(frame.getWidth()==8&&frame.getHeight()==6&&data.remaining()==192,"frame dimensions and bytes");expect((data.get(4)&255)==30&&(data.get(5)&255)==0&&(data.get(6)&255)==15&&(data.get(7)&255)==255,"frame RGBA order");Bitmap fb=Bitmap.createBitmap(8,6,Bitmap.Config.ARGB_8888);owned.add(fb);fb.copyPixelsFromBuffer(data);expect(Arrays.equals(pixels(fb),expected),"frame to bitmap pixels");}expect(decoder.decodeNext()==null,"single frame exhaustion");}
   try(var animation=ca.mpreg.imagedecoder.ImageDecoder.Companion.open(new ByteArrayInputStream(Base64.getDecoder().decode(GIF)),false)){for(int i=0;i<2;i++)try(var frame=animation.decodeNext()){expect(frame!=null,"animation frame "+i);ByteBuffer data=frame.getImage();expect((data.get(0)&255)==(i==0?255:0)&&(data.get(1)&255)==(i==1?255:0),"animation color "+i);}expect(animation.decodeNext()==null,"animation exhaustion");}
   Bitmap recycled=Bitmap.createBitmap(1,1,Bitmap.Config.ARGB_8888);recycled.recycle();recycled.recycle();failed=false;try{recycled.getPixel(0,0);}catch(IllegalStateException e){failed=true;}expect(failed&&recycled.isRecycled(),"recycled bitmap rejects access");
   JsonObject out=new JsonObject();out.addProperty("pass",true);out.addProperty("count",checks.size());out.add("checks",checks);return out.toString();
  }finally{for(Bitmap b:owned)if(b!=null)b.recycle();}
 }
}
